#include <Arduino.h>

const byte glyphs[10] = {0x3F,0x06,0x5B,0x4F,0x66,0x6D,0x7D,0x07,0x7F,0x6F};
char pending = 0;
unsigned long lastByte = 0;

void showDigit(char c) {
  if (c < '0' || c > '9') return;
  byte mask = glyphs[c - '0'];
  for (byte i = 0; i < 7; ++i) {
    digitalWrite(2 + i, (mask & (1 << i)) ? LOW : HIGH);
  }
  digitalWrite(9, HIGH);
}

void finishFrame() {
  if (pending) showDigit(pending);
  pending = 0;
}

void setup() {
  for (byte p = 2; p <= 9; ++p) {
    digitalWrite(p, HIGH);
    pinMode(p, OUTPUT);
  }
  Serial.begin(9600);
}

void loop() {
  while (Serial.available() > 0) {
    char c = Serial.read();
    lastByte = millis();
    if (c == '\n' || c == '\r') finishFrame();
    else if (c >= '0' && c <= '9') pending = c;
  }
  if (pending && (unsigned long)(millis() - lastByte) >= 20) finishFrame();
}
